/* The string for a glyph name (sorted table, binary search), or NULL. */
static inline const char *r3mono_name(const char *name) {
    int lo = 0, hi = (int)(sizeof r3mono_names / sizeof r3mono_names[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2, c = strcmp(name, r3mono_names[mid].name);
        if (c == 0) return r3mono_names[mid].utf8;
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return 0;
}
